279	     in this list.
280	
281	     @param c collection containing nodes to be removed from this list
282	     @return {@code true} if nodes were removed from this list
283	     */
284	    @Override
285	    public boolean removeAll(Collection<?> c) {
286	        boolean anyRemoved = false;
287	        for (Object o : c) {
288	            anyRemoved |= this.remove(o);
289	        }
290	        return anyRemoved;
291	    }
