298	     @param toRemove collection containing nodes to be retained in this list
299	     @return {@code true} if nodes were removed from this list
300	     @since 1.17.1
301	     */
302	    @Override
303	    public boolean retainAll(Collection<?> toRemove) {
304	        boolean anyRemoved = false;
305	        for (Iterator<T> it = this.iterator(); it.hasNext(); ) {
306	            T el = it.next();
307	            if (!toRemove.contains(el)) {
308	                it.remove();
309	                anyRemoved = true;
310	            }
311	        }
312	        return anyRemoved;
313	    }
