316	     Remove from the list, and from the DOM, all nodes in this list that mach the given predicate.
317	
318	     @param filter a predicate which returns {@code true} for nodes to be removed
319	     @return {@code true} if nodes were removed from this list
320	     */
321	    @Override
322	    public boolean removeIf(Predicate<? super T> filter) {
323	        boolean anyRemoved = false;
324	        for (Iterator<T> it = this.iterator(); it.hasNext(); ) {
325	            T node = it.next();
326	            if (filter.test(node)) {
327	                it.remove();
328	                anyRemoved = true;
